const rows = $input.all().map(item => item.json);

// Group by client_name + platform
const groups = {};
for (const row of rows) {
  const key = `${row.client_name}|${row.platform}`;
  if (!groups[key]) groups[key] = [];
  groups[key].push(row);
}

const results = [];

for (const key in groups) {
  const periods = groups[key].sort((a, b) =>
    a.reporting_period.localeCompare(b.reporting_period)
  );

  // Last period = current, second-to-last = previous
  const current = periods[periods.length - 1];
  const previous = periods.length > 1 ? periods[periods.length - 2] : null;

  results.push({
    json: {
      client_name: current.client_name,
      platform: current.platform,
      campaign_name: current.campaign_name,
      current,
      previous
    }
  });
}

return results;

function safeDiv(numerator, denominator) {
  if (!denominator || denominator === 0) return 0;
  return numerator / denominator;
}

function calcMetrics(period) {
  return {
    ctr: safeDiv(period.clicks, period.impressions) * 100,
    conversion_rate: safeDiv(period.conversions, period.clicks) * 100,
    cpc: safeDiv(period.spend, period.clicks),
    cpa: safeDiv(period.spend, period.conversions),
    roas: safeDiv(period.revenue, period.spend)
  };
}

function pctChange(current, previous) {
  if (!previous || previous === 0) return 0;
  return ((current - previous) / previous) * 100;
}

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  const current = data.current;
  const previous = data.previous;

  const currentMetrics = calcMetrics(current);
  const previousMetrics = previous ? calcMetrics(previous) : null;

  const comparison = previousMetrics ? {
    ctr_change: pctChange(currentMetrics.ctr, previousMetrics.ctr),
    conversion_rate_change: pctChange(currentMetrics.conversion_rate, previousMetrics.conversion_rate),
    cpc_change: pctChange(currentMetrics.cpc, previousMetrics.cpc),
    cpa_change: pctChange(currentMetrics.cpa, previousMetrics.cpa),
    roas_change: pctChange(currentMetrics.roas, previousMetrics.roas)
  } : null;

  results.push({
    json: {
      client_name: data.client_name,
      platform: data.platform,
      campaign_name: data.campaign_name,
      current,
      previous,
      current_metrics: currentMetrics,
      previous_metrics: previousMetrics,
      comparison
    }
  });
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const d = item.json;

  const prompt = `
You are a marketing performance analyst. Use ONLY the data below. Do not invent numbers or results.

Client: ${d.client_name}
Platform: ${d.platform}
Campaign: ${d.campaign_name}

CURRENT PERIOD (${d.current.reporting_period}):
Spend: $${d.current.spend}
Impressions: ${d.current.impressions}
Clicks: ${d.current.clicks}
Conversions: ${d.current.conversions}
Revenue: $${d.current.revenue}
CTR: ${d.current_metrics.ctr.toFixed(2)}%
Conversion Rate: ${d.current_metrics.conversion_rate.toFixed(2)}%
CPC: $${d.current_metrics.cpc.toFixed(2)}
CPA: $${d.current_metrics.cpa.toFixed(2)}
ROAS: ${d.current_metrics.roas.toFixed(2)}

PREVIOUS PERIOD (${d.previous.reporting_period}):
Spend: $${d.previous.spend}
CTR: ${d.previous_metrics.ctr.toFixed(2)}%
Conversion Rate: ${d.previous_metrics.conversion_rate.toFixed(2)}%
CPC: $${d.previous_metrics.cpc.toFixed(2)}
CPA: $${d.previous_metrics.cpa.toFixed(2)}
ROAS: ${d.previous_metrics.roas.toFixed(2)}

PERCENTAGE CHANGE:
CTR: ${d.comparison.ctr_change.toFixed(1)}%
Conversion Rate: ${d.comparison.conversion_rate_change.toFixed(1)}%
CPC: ${d.comparison.cpc_change.toFixed(1)}%
CPA: ${d.comparison.cpa_change.toFixed(1)}%
ROAS: ${d.comparison.roas_change.toFixed(1)}%

Respond ONLY in this exact JSON format, with no extra text:
{
  "performance_summary": "2-3 sentence summary",
  "key_wins": ["win 1", "win 2"],
  "areas_for_attention": ["issue 1", "issue 2"],
  "recommendations": ["recommendation 1", "recommendation 2"]
}
`.trim();

  results.push({
    json: {
      ...d,
      ai_prompt: prompt
    }
  });
}

return results;

const items = $input.all();
const originalItems = $('Prepare AI Input').all(); // pulls back the earlier data by index
const results = [];

for (let i = 0; i < items.length; i++) {
  const d = items[i].json;
  const original = originalItems[i].json; // has client_name, current, previous, current_metrics, comparison

  let rawText = d.candidates[0].content.parts[0].text;
  rawText = rawText.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();

  let aiInsights;
  try {
    aiInsights = JSON.parse(rawText);
  } catch (err) {
    aiInsights = {
      performance_summary: "AI response could not be parsed.",
      key_wins: [],
      areas_for_attention: [],
      recommendations: [],
      parse_error: err.message
    };
  }

  results.push({
    json: {
      ...original,
      ai_insights: aiInsights
    }
  });
}

return results;

const items = $input.all();
const results = [];

function metricClass(val, invert = false) {
  const isGood = invert ? val <= 0 : val >= 0;
  return isGood ? 'positive' : 'negative';
}

function arrow(val) {
  return val >= 0 ? '▲' : '▼';
}

for (const item of items) {
  const d = item.json;
  const c = d.current;
  const cm = d.current_metrics;
  const comp = d.comparison;
  const ai = d.ai_insights;

  const html = `<!DOCTYPE html>
