    .negative { color: #dc2626; }
    ul { padding-left: 20px; margin: 8px 0; }
    li { margin-bottom: 6px; font-size: 14px; }
    .summary-text { font-size: 14px; line-height: 1.6; color: #374151; margin: 0; }
    .footer { padding: 20px 30px; text-align: center; font-size: 12px; color: #9ca3af; }
    @media (max-width: 600px) {
      body { padding: 20px 12px; }
      .section { padding: 20px 18px; }
      .header { padding: 24px 18px; }
      .metrics-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    }
  </style>
</head>
<body>
  <div class="report">
    <div class="header">
      <h1>📊 Marketing Performance Report</h1>
      <p>${d.client_name} · ${d.platform} · ${d.campaign_name} · ${c.reporting_period}</p>
    </div>
    <div class="section">
      <h2>Campaign Overview</h2>
      <div class="metrics-grid">
        <div class="metric-card"><div class="label">Spend</div><div class="value">$${c.spend.toLocaleString()}</div></div>
        <div class="metric-card"><div class="label">Impressions</div><div class="value">${c.impressions.toLocaleString()}</div></div>
        <div class="metric-card"><div class="label">Clicks</div><div class="value">${c.clicks.toLocaleString()}</div></div>
        <div class="metric-card"><div class="label">Conversions</div><div class="value">${c.conversions}</div></div>
        <div class="metric-card"><div class="label">Revenue</div><div class="value">$${c.revenue.toLocaleString()}</div></div>
      </div>
    </div>
    <div class="section">
      <h2>Key Metrics</h2>
      <div class="metrics-grid">
