        <div class="metric-card"><div class="label">CPC</div><div class="value">$${cm.cpc.toFixed(2)}</div><div class="change ${metricClass(comp.cpc_change, true)}">${arrow(comp.cpc_change)} ${Math.abs(comp.cpc_change).toFixed(1)}%</div></div>
        <div class="metric-card"><div class="label">CPA</div><div class="value">$${cm.cpa.toFixed(2)}</div><div class="change ${metricClass(comp.cpa_change, true)}">${arrow(comp.cpa_change)} ${Math.abs(comp.cpa_change).toFixed(1)}%</div></div>
        <div class="metric-card"><div class="label">ROAS</div><div class="value">${cm.roas.toFixed(2)}</div><div class="change ${metricClass(comp.roas_change)}">${arrow(comp.roas_change)} ${Math.abs(comp.roas_change).toFixed(1)}%</div></div>
