      <ul>${ai.key_wins.map(w => `<li>${w}</li>`).join('')}</ul>
    </div>
    <div class="section">
      <h2>⚠️ Areas for Attention</h2>
      <ul>${ai.areas_for_attention.map(a => `<li>${a}</li>`).join('')}</ul>
    </div>
    <div class="section" style="border-bottom: none;">
      <h2>💡 Recommendations</h2>
      <ul>${ai.recommendations.map(r => `<li>${r}</li>`).join('')}</ul>
    </div>
    <div class="footer">Generated by AgencyReport AI · ${new Date().toLocaleDateString()}</div>
  </div>
</body>
</html>`;

  results.push({
    json: {
      client_name: d.client_name,
      platform: d.platform,
      campaign_name: d.campaign_name,
      reporting_period: c.reporting_period,
      report_html: html
    }
  });
}

return results;
